@startuml

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

abstract class Role {}

class Member {}
class Trainer {}

class FitnessCenter {
  + name : string
  + address : string
}

class Room {
  + roomNumber : int
  + maxCapacity : int
}

class Session {
  + sessionDate : date
  + startHour : time
}

class GroupSession extends Session {
  + type : string
}

abstract class Participation {}

class IndividualParticipation extends Participation {}
class GroupParticipation extends Participation {}

Person "1" -- "*" Role
Member --|> Role
Trainer --|> Role

FitnessCenter "0..*" -- "*" Room
Room "1" *-- "*" Session

GroupSession "1" -- "1" Trainer
IndividualParticipation "1" -- "1" Person
GroupParticipation "1" -- "1" GroupSession
GroupParticipation "1" -- "1" Member

@enduml

